import java.util.*;

public class LinkedList {
    Node head;
    int length;

    public static class Node {
        int value;
        Node next;

        public Node(int value) {
            this.value = value;
        }
    }

    public LinkedList() {
        this.head = null;
        this.length = 0;
    }

    public void add(int X, int pos) {
        Node node = new Node(X);
        this.length++;

        // is head
        if (this.head == null || pos == 0) {
            node.next = head;
            this.head = node;
            if (pos != 0) {
                System.out.print("add_last");
            }
            return;
        }

        // find index to place at
        Node nodeBefore = this.head;
        int index = 0;
        while (nodeBefore.next != null && index < pos - 1) {
            index++;
            nodeBefore = nodeBefore.next;
        }

        // is tail
        if (nodeBefore.next == null) {
            nodeBefore.next = node;
            if (index + 1 != pos) {
                System.out.print("add_last");
            }
            return;
        }

        // is in middle
        Node temp = nodeBefore.next;
        nodeBefore.next = node;
        node.next = temp;
    }

    public void remove(int pos) {
        if (pos < 0 || pos > this.length - 1 || this.head == null) {
            System.out.print("remove_failed");
            return;
        }
        this.length--;

        if (this.length == 0) {
            this.head = null;
            return;
        }

        if (pos == 0) {
            this.head = this.head.next;
            return;
        }

        Node nodeBefore = head;
        int index = 0;
        while (nodeBefore.next != null && index < pos - 1) {
            nodeBefore = nodeBefore.next;
            index++;
        }

        nodeBefore.next = nodeBefore.next.next;
    }

    public void print() {
        Node currentNode = head;

        while (currentNode != null) {
            System.out.print(currentNode.value + "#");
            currentNode = currentNode.next;
        }
    }

    public void reverse() {
        Node prev = null;
        Node current = this.head;
        Node next = null;
        while (current != null) {
            next = current.next;
            current.next = prev;
            prev = current;
            current = next;
        }
        this.head = prev;
    }

    public void printIsPalindrome() {
        List<Integer> list = new ArrayList<Integer>();
        Node current = this.head;

        while (current != null) {
            list.add(current.value);
            current = current.next;
        }

        for (int i = 0; i < list.size() / 2; i++) {
            if (!list.get(i).equals(list.get(list.size() - i - 1))) {
                System.out.print("false");
                return;
            }
        }

        System.out.print("true");
    }


