    } 


    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int N = in.nextInt();
        for (int t = 0; t < N; t++) {
            int K = in.nextInt();
            LinkedList list = new LinkedList();
            for (int i = 0; i < K; i++) {
                String op = in.next();
                switch (op) {
                    case "add":
                        int x = in.nextInt();
                        int pos = in.nextInt();
                        list.add(x, pos);
                        break;
                    case "remove":
                        int rmPos = in.nextInt();
                        list.remove(rmPos);
                        break;
                    case "print":
                        list.print();
                        break;
                    case "reverse":
                        list.reverse();
                        break;
                    case "is_palindrom":
                        list.printIsPalindrome();
                        break;
                    case "remove_all":
                        int numberToRemove = in.nextInt();
                        list.removeAll(numberToRemove);
                        break;

                }
            }
            System.out.println();
        }
    }
}

